// ---
// relationships:
//   implements: documentation
//   references: library, api
// ---
import * as NodePath from "node:path";

export const generatedMarker =
  "<!-- Generated by task cli:docs from docs/api.md; edit the source. -->";
const areas = [
  ["client", "Client and transport", "Library"],
  ["authentication", "Authentication API", "Library"],
  ["profiles", "Profiles and credentials", "Library"],
  ["errors", "Errors", "Library"],
  ["types", "Shared types and constants", "Library"],
  ["projects", "Projects API", "Workspace facades"],
  ["threads", "Threads API", "Threads"],
  ["thread-lifecycle", "Thread lifecycle API", "Threads"],
  ["thread-runs", "Thread runs and inspection", "Threads"],
  ["thread-state", "Thread state and helpers", "Threads"],
  ["shell", "Shell API", "Threads"],
  ["server-summary", "Server API summary", "Server and automation"],
  ["server", "Server API", "Server and automation"],
  ["server-methods", "Server API methods", "Server and automation"],
  ["schedules", "Scheduled tasks API", "Server and automation"],
  ["vcs", "Version control API", "Workspace facades"],
  ["terminal", "Terminal API", "Workspace facades"],
];

function areaOf(name, summary = false) {
  if (/^T3.*Error$|^(?:isT3Error|isRpcErrorOfTag|RpcErrorRecord)$/u.test(name)) return "errors";
  if (/^Auth|^(?:hasScope|ensureScopes|grantedScopes|watchAccess)$/u.test(name))
    return "authentication";
  if (/^Profile|^(?:memoryCredentialStore|fileCredentialStore)$/u.test(name)) return "profiles";
  if (name === "ServerApi") return summary ? "server-summary" : "server";
  if (name.startsWith("ScheduledTask")) return "schedules";
  const facades = {
    ProjectsApi: "projects",
    ThreadsApi: "threads",
    ShellApi: "shell",
    VcsApi: "vcs",
    TerminalApi: "terminal",
  };
  if (Object.hasOwn(facades, name)) return facades[name];
  if (/^(?:T3Client|RpcClient|CommandDispatcher|consoleLogger)$/u.test(name)) return "client";
  if (
    /^(?:threadId|THREAD_SEARCH_MAX_LIMIT|TurnTokenUsage|ProviderUserInputAnswer|ModelSelection|latestDiffTurnCount|applyThreadEvent|pendingRequests|runOutcome|assistantMessageForRun|activeRun|threadPhase|watchThread|isRunTerminalStatus|isRunActiveStatus|isTurnItemOfType)$/u.test(
      name,
    ) ||
    name.startsWith("OrchestrationV2")
  )
    return "thread-state";
  return "types";
}

// Inspect structural lines only outside code fences. API examples can contain headings.
function structuralLines(text) {
  let fence;
  let offset = 0;
  const result = [];
  for (const line of text.split(/(?<=\n)/u)) {
    const marker = line.match(/^\s{0,3}(`{3,}|~{3,})/u)?.[1];
    if (marker && !fence) fence = marker;
    else if (marker && marker[0] === fence?.[0] && marker.length >= fence.length) fence = undefined;
    else if (!fence) result.push({ line: line.trimEnd(), offset });
    offset += line.length;
  }
  if (fence) throw new Error("Unclosed code fence in docs/api.md.");
  return result;
}

function parseReference(content) {
  const text = content.replace(/^---\n[\s\S]*?\n---\n/u, "").trimStart();
  const lines = structuralLines(text);
  const firstBody = lines.find(({ line }) => /^<a name="[^"]+"><\/a>$/u.test(line));
  const firstSummary = lines.find(({ line }) => line.startsWith("## "));
  if (!firstBody || !firstSummary || firstBody.offset <= firstSummary.offset)
    throw new Error("Expected generated API summaries followed by anchored API bodies.");
  const preamble = text.slice(0, firstSummary.offset);
  const units = [];
  const summaryText = text.slice(firstSummary.offset, firstBody.offset);
  const summaries = [...summaryText.matchAll(/^## (.+)\n\n<dl>\n([\s\S]*?)<\/dl>\s*/gmu)];
  if (summaries.map(([raw]) => raw).join("") !== summaryText)
    throw new Error("Unrecognized API summary content; refusing to omit it.");
  for (const [, category, entries] of summaries) {
    const items = [
      ...entries.matchAll(/<dt><a href="#([^"]+)">[^\n]*<\/dt>\n<dd>[\s\S]*?<\/dd>\n/gu),
    ];
    if (items.map(([raw]) => raw).join("") !== entries)
      throw new Error(`Unrecognized ${category} summary entry; refusing to omit it.`);
    for (const [raw, name] of items) units.push({ raw, category, area: areaOf(name, true) });
  }
  // An anchor belongs to the following H2/H3 section, including all signatures and prose.
  const boundaries = lines
    .filter(
      ({ line, offset }) =>
        offset >= firstBody.offset &&
        (/^<a name="[^"]+"><\/a>$/u.test(line) || line.startsWith("## ")),
    )
    .filter(
      (entry, index, all) =>
        !entry.line.startsWith("## ") ||
        !all[index - 1]?.line.startsWith("<a ") ||
        text.slice(all[index - 1].offset + all[index - 1].line.length, entry.offset).trim() !== "",
    );
  let area;
  for (let index = 0; index < boundaries.length; index++) {
    const start = boundaries[index];
    const raw = text.slice(start.offset, boundaries[index + 1]?.offset ?? text.length);
    const name = start.line.match(/^<a name="([^"]+)">/u)?.[1];
    if (name && !/[+.]/u.test(name)) area = areaOf(name);
    else if (name === "ThreadsApi+create") area = "thread-lifecycle";
    else if (name === "ThreadsApi+startTurn") area = "thread-runs";
    else if (name?.startsWith("ServerApi+")) area = "server-methods";
    else if (!name) {
      if (start.line !== "## Profile and credential types")
        throw new Error(`Unrecognized API section: ${start.line}`);
      area = "profiles";
    }
    if (!area) throw new Error(`API member has no enclosing public section: ${start.line}`);
    units.push({ raw, area });
  }
  return { preamble, units, categories: summaries.map(([, category]) => category) };
}

function renderUnits(units) {
  let body = "";
  let category;
  for (const unit of units) {
    if (unit.category !== category) {
      if (category) body += "</dl>\n\n";
      if (unit.category) body += `## ${unit.category}\n\n<dl>\n`;
      category = unit.category;
    }
    if (body && unit.raw.startsWith("## ")) body = `${body.trimEnd()}\n\n`;
    body += unit.raw;
  }
  if (category) body += "</dl>\n\n";
  return body;
}

function anchors(body) {
  return structuralLines(body).flatMap(({ line }) => {
    const explicit = line.match(/^<a (?:name|id)="([^"]+)">/u)?.[1];
    if (explicit) return [explicit];
    const heading = line.match(/^#+ (.+)$/u)?.[1];
    return heading
      ? [
          heading
            .toLowerCase()
            .replace(/[^\w -]/gu, "")
            .replace(/ /gu, "-"),
        ]
      : [];
  });
}

export function rewriteLinks(body, filename, owners) {
  const filenames = new Set(owners.values());
  function rewrite(href) {
    if (/^(?:[a-z][a-z\d+.-]*:|\/\/)/iu.test(href)) return href;
    const [path, anchor] = href.split("#");
    if (filenames.has(path)) return href;
    if (!path || NodePath.posix.normalize(path) === "api.md") {
      if (!anchor) return "library-reference.md";
      const owner = owners.get(decodeURIComponent(anchor));
      if (!owner) throw new Error(`Unresolved API anchor: ${href}`);
      return `${owner === filename ? "" : owner}#${anchor}`;
    }
    return `https://github.com/wyrd-company/t3code-client/blob/main/${NodePath.posix.normalize(`docs/${path}`)}${anchor === undefined ? "" : `#${anchor}`}`;
  }
  let output = "";
  let cursor = 0;
  for (const { line, offset } of structuralLines(body)) {
    output +=
      body.slice(cursor, offset) +
      line.replace(/\]\(([^)]+)\)|\bhref=("|')([^"']+)\2/gu, (match, markdown, quote, html) =>
        markdown ? `](${rewrite(markdown)})` : `href=${quote}${rewrite(html)}${quote}`,
      );
    cursor = offset + line.length;
  }
  return output + body.slice(cursor);
}

export function projectReference(content, maxLines = 480) {
  const { preamble, units, categories } = parseReference(content);
  const pages = [];
  for (const [area, title, group] of areas) {
    const selected = units.filter((unit) => unit.area === area);
    let batch = [];
    let part = 1;
    function flush() {
      if (!batch.length) return;
      const pageTitle = `${title}${part === 1 ? "" : ` (${part})`}`;
      pages.push({
        filename: `library-${area}${part === 1 ? "" : `-${part}`}.md`,
        title: pageTitle,
        group,
        units: batch,
        body: `# ${pageTitle}\n\n${renderUnits(batch)}`,
      });
      part++;
      batch = [];
    }
    for (const unit of selected) {
      if (renderUnits([unit]).split("\n").length > maxLines)
        throw new Error(
          `API block exceeds ${maxLines} lines; split its source structure: ${unit.raw.slice(0, 80)}`,
        );
      if (batch.length && renderUnits([...batch, unit]).split("\n").length > maxLines) flush();
      batch.push(unit);
    }
    flush();
  }
  const landing = {
    filename: "library-reference.md",
    title: "Library API",
    group: "Library",
    body: preamble,
  };
  for (const category of categories) {
    landing.body += `## ${category}\n\n`;
    for (const page of pages.filter((page) =>
      page.units.some((unit) => unit.category === category),
    ))
      landing.body += `- [${page.title}](${page.filename})\n`;
    landing.body += "\n";
  }
  landing.body += "## Reference pages\n\n";
  for (const page of pages) landing.body += `- [${page.title}](${page.filename})\n`;
  pages.unshift(landing);
  const owners = new Map();
  // The landing retains category heading anchors. Child summary headings are local navigation.
  for (const page of pages) {
    for (const anchor of anchors(page.body)) {
      if (!owners.has(anchor)) owners.set(anchor, page.filename);
      else if (
        owners.get(anchor) !== page.filename &&
        !categories.map((c) => c.toLowerCase()).includes(anchor)
      )
        throw new Error(`API anchor has multiple owner pages: ${anchor}`);
    }
  }
  return pages.map(({ filename, title, group, body }, index) => ({
    filename,
    title,
    group,
    order: 6 + index,
    content: `---\nproduct: t3c\ntitle: ${JSON.stringify(title)}\norder: ${6 + index}\nrelationships:\n  references: [library, api]\n---\n\n${generatedMarker}\n\n${rewriteLinks(body, filename, owners).trimEnd()}\n`,
  }));
}
